export function PictureInPicture({
  corner = "{{corner}}",
  width = {{width}},
  accent = "{{accent}}",
  closeBtn = {{closeBtn}},
}) {
  const pos = {
    "bottom-right": { right: 10, bottom: 10 },
    "bottom-left": { left: 10, bottom: 10 },
    "top-right": { right: 10, top: 10 },
    "top-left": { left: 10, top: 10 },
  }[corner] ?? { right: 10, bottom: 10 };
  return (
    <div style={{ position: "relative", maxWidth: 380, aspectRatio: "380 / 220", borderRadius: 10,
      overflow: "hidden", border: "1px solid #24143022" }}>
      <div style={{ position: "absolute", inset: 0 }} aria-hidden="true">
        <svg viewBox="0 0 380 220" width="100%" height="100%">
          <rect width="380" height="220" fill="#FAF7F2" />
          <rect x="20" y="20" width="180" height="14" rx="7" fill="#24143022" />
          <rect x="20" y="46" width="260" height="10" rx="5" fill="#24143014" />
          <rect x="20" y="66" width="220" height="10" rx="5" fill="#24143014" />
        </svg>
      </div>
      <div style={{ position: "absolute", ...pos, width, borderRadius: 8, border: `2px solid ${accent}`,
        overflow: "hidden", boxShadow: "0 8px 20px rgba(36,20,48,.28)", background: "#241430" }}>
        <video style={{ display: "block", width: "100%", aspectRatio: "16 / 9", background: "#241430" }}
          muted autoPlay loop playsInline aria-label="Picture-in-picture video">
          {/* Provide a real <source src="your-video.mp4" type="video/mp4" /> for playback */}
        </video>
        {closeBtn && (
          <button type="button" aria-label="Close picture-in-picture"
            style={{ position: "absolute", top: 4, right: 4, width: 20, height: 20, borderRadius: "50%",
              border: "none", color: "#241430", fontSize: 13, lineHeight: 1, cursor: "pointer", background: accent }}>
            &times;
          </button>
        )}
      </div>
    </div>
  );
}
